package dashboard

import "strings"

// The experience extends the existing document and its authenticated flows.
// All assets, charts and interactions stay in this one local HTML response.
func experiencePage() string {
	document := strings.Replace(page, "</style>", experienceCSS+themeCSS+"</style>", 1)
	document = strings.Replace(document, "<main>", `<a class="skip-link" href="#org-live">Skip to live org</a><main>`, 1)
	document = strings.Replace(document, `<div class="grid">`, experienceHero+`<div class="grid">`+employeePage+controlPage, 1)
	document = strings.Replace(document, "</nav>", `<a href="#proposals">Proposals</a><a href="#tools">Tool submissions</a></nav>`, 1)
	document = strings.Replace(document, "</main>", "</main>"+experienceDrawer+shortcutPanel, 1)
	document = strings.Replace(document, "\nrefresh();", "\n"+experienceScript+"\n"+employeeScript+"\n"+controlScript+"\nrefresh();", 1)
	document = strings.Replace(document, "const sessionToken=", localeScript+"\nconst sessionToken=", 1)
	return localizeShell(document)
}

const experienceHero = `
<div class="watch-controls"><label class="agent-find">Find an agent<input id="agent-search" type="search" autocomplete="off" placeholder="Name, model or state…" aria-controls="org-graph"></label><div class="watch-actions"><button id="watch-pause" type="button" aria-pressed="false">Pause live</button><div class="preferences"><label>Theme<select id="theme-choice"><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></label><label>Language<select id="language-choice"><option value="en">EN</option><option value="zh-TW">中文</option></select></label></div></div></div>
<section id="now" class="now-strip" aria-label="Now"><p class="error" id="now-error"></p><div id="now-content" class="now-grid"><p class="empty">Reading the current org signals…</p></div></section>
<section id="org-live" class="org-hero" aria-labelledby="graph-heading"><div class="hero-head"><div><p class="eyebrow">Live org / Recorded activity</p><h2 id="graph-heading">Org in motion</h2><p class="muted hero-caption">Open an agent to see its thinking, messages and guard refusals.</p></div><div class="graph-legend"><span class="state running">Running</span><span class="state verifying">Verifying</span><span class="state idle">Idle</span><span class="state failed">Failed</span></div></div><p class="error" id="graph-error"></p><div id="org-graph" class="graph-root" aria-live="off"><p class="empty">Reading configured instances and recorded lanes…</p></div><div class="hero-foot"><span id="graph-count">Waiting for records</span><span>Grouped by level · Sparklines cover the last hour</span></div></section>
`

const experienceDrawer = `
<dialog id="agent-drawer" class="agent-drawer" aria-labelledby="drawer-name"><div class="drawer-header"><div><p class="eyebrow" id="drawer-level">Agent</p><h2 id="drawer-name">Recorded agent</h2><p id="drawer-model" class="muted"></p><p id="drawer-supervisor" class="muted"></p><p id="drawer-level-source" class="muted"></p></div><button id="drawer-close" type="button" aria-label="Close agent drawer">Close</button></div><p id="drawer-error" class="error" role="status"></p><div class="drawer-body"><section><h3>Lifecycle timeline</h3><p class="muted">Newest 1000 recorded events</p><div id="drawer-lifecycle" class="drawer-records"><p class="empty">Loading recorded lifecycle…</p></div></section><section><div class="drawer-section-head"><h3>Thinking timeline</h3><label><input id="drawer-follow" type="checkbox" checked> Follow</label></div><div id="drawer-timeline" class="thinking-stream"><p class="empty">Loading recorded output…</p></div></section><section><h3>Messages</h3><div id="drawer-messages" class="drawer-records"></div></section><section><h3>Refusals</h3><div id="drawer-refusals" class="drawer-records"></div></section></div><form id="drawer-compose" class="drawer-compose"><label for="drawer-text">Message this agent</label><textarea id="drawer-text" rows="3" maxlength="4000" required placeholder="Write a message…"></textarea><button type="submit" id="drawer-send" class="send-button">Send message</button><span id="drawer-send-status" class="send-status" role="status"></span></form></dialog>
`

// The keyboard shortcuts live here, not in the header: "?" opens this panel,
// and a modal dialog closes on Escape by itself.
const shortcutPanel = `
<dialog id="shortcut-panel" class="shortcut-panel" aria-labelledby="shortcut-title"><div class="shortcut-head"><h2 id="shortcut-title">Keyboard shortcuts</h2><button id="shortcut-close" type="button">Close</button></div><dl class="shortcut-list"><div><dt><kbd>/</kbd></dt><dd>Find an agent</dd></div><div><dt><kbd>g o</kbd></dt><dd>Go to the live org</dd></div><div><dt><kbd>g a</kbd></dt><dd>Go to analytics</dd></div><div><dt><kbd>g d</kbd></dt><dd>Go to decisions</dd></div><div><dt><kbd>?</kbd></dt><dd>Show this list</dd></div><div><dt><kbd>Esc</kbd></dt><dd>Close this list</dd></div></dl><p class="muted">Shortcuts are inactive while you type in a field.</p></dialog>
`

